using Nakama.Api.BuildingBlocks.Time;
namespace Nakama.Api.Modules.Tasks.Domain;
public sealed class Subtask
{ private Subtask(){} private Subtask(Guid taskId,string title,int position,Guid creator,DateTimeOffset now){if(taskId==Guid.Empty||creator==Guid.Empty||position<1)throw new ArgumentException("Invalid subtask.");Id=Guid.NewGuid();TaskId=taskId;SetTitle(title);Position=position;CreatedByUserId=creator;CreatedAt=UpdatedAt=now;} public Guid Id{get;private set;} public Guid TaskId{get;private set;} public string Title{get;private set;}=null!; public int Position{get;private set;} public bool IsCompleted{get;private set;} public Guid CreatedByUserId{get;private set;} public Guid? CompletedByUserId{get;private set;} public DateTimeOffset CreatedAt{get;private set;} public DateTimeOffset? CompletedAt{get;private set;} public DateTimeOffset UpdatedAt{get;private set;}
 public static Subtask Create(Guid taskId,string title,int position,Guid creator,IClock clock)=>new(taskId,title,position,creator,clock.UtcNow); public void UpdateTitle(string title,IClock c){SetTitle(title);UpdatedAt=c.UtcNow;} public void Complete(Guid user,IClock c){if(IsCompleted)throw new InvalidOperationException("Already completed.");if(user==Guid.Empty)throw new ArgumentException("User required.");IsCompleted=true;CompletedByUserId=user;CompletedAt=UpdatedAt=c.UtcNow;} public void Reopen(IClock c){if(!IsCompleted)throw new InvalidOperationException("Not completed.");IsCompleted=false;CompletedByUserId=null;CompletedAt=null;UpdatedAt=c.UtcNow;} public void Reposition(int position){if(position<1)throw new ArgumentException("Position required.");Position=position;} private void SetTitle(string title){Title=title?.Trim()??"";if(string.IsNullOrWhiteSpace(Title)||Title.Length>300)throw new ArgumentException("Title is required.");}}
